    if ((!(this->_locked))) {
        // raise RuntimeError("Lock is not acquired.")
        throw ::tpy::RuntimeError("Lock is not acquired.");
    }
    // self._locked = False
    this->_locked = false;
    // _wake_one(self._waiters)
    _wake_one(this->_waiters);
